<script setup lang="ts">
import { computed,onMounted,ref,watch } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage,ElMessageBox } from 'element-plus'
import { reviewProvider } from '@/services/review'
import { useAuthStore } from '@/stores/auth'
import { ApiError } from '@/services/api'
import type { ReviewListItem,ReviewDetail } from '@/types/review'
import { reportStatusLabels } from '@/utils/review'
import { formLabels } from '@/utils/report'
import { formatBeijingTime } from '@/utils/filing'
import ReviewTimeline from '@/components/ReviewTimeline.vue'
const route=useRoute();const auth=useAuthStore();const level=computed(()=>route.path.startsWith('/city')?'city':'province');const rows=ref<ReviewListItem[]>([]);const detail=ref<ReviewDetail|null>(null);const visible=ref(false);const busy=ref(false);const acting=ref(false);const error=ref('');const periodCode=ref('');const status=ref('');const page=ref(1);const total=ref(0);const returnVisible=ref(false);const comment=ref('');const commentError=ref('')
async function load(){busy.value=true;error.value='';try{const r=await reviewProvider.list(level.value,{periodCode:periodCode.value.trim()||undefined,status:status.value||undefined,page:page.value-1,size:20},auth.token!);rows.value=r.data.items;total.value=r.data.total}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function open(id:string){detail.value=null;visible.value=true;busy.value=true;try{detail.value=(await reviewProvider.detail(level.value,id,auth.token!)).data}catch(e){visible.value=false;ElMessage.error((e as Error).message)}finally{busy.value=false}}
async function act(action:'approve'|'return'){if(!detail.value)return;const d=detail.value;if(action==='approve'){try{await ElMessageBox.confirm('确认通过当前提交版本？','审核确认',{type:'warning'})}catch{return}}else if(comment.value.trim().length>500){commentError.value='备注最多500字';return}acting.value=true;try{await reviewProvider.act(level.value,d.reportId,action,{expectedVersion:d.currentVersion,submissionVersion:d.submissionVersion,...(action==='return'?{comment:comment.value.trim()||null}:{})},auth.token!);returnVisible.value=false;ElMessage.success(action==='approve'?'审核已通过':'报表已退回');await open(d.reportId);await load()}catch(e){if(e instanceof ApiError){commentError.value=e.fieldErrors.comment??'';if(e.status===409){returnVisible.value=false;await open(d.reportId);await load();ElMessage.warning('状态或版本已变化，已刷新，请重新确认');return}if(e.status===404){visible.value=false;await load()}}ElMessage.error((e as Error).message)}finally{acting.value=false}}
function reset(){periodCode.value='';status.value='';page.value=1;void load()}
onMounted(load);watch(level,()=>{visible.value=false;reset()})
</script>
<template><section><div class="page-heading"><div><h1>{{level==='city'?'市级辖区报表审核':'省级报表审核'}}</h1><p>默认显示本级待审，所有人数和表单来自最新提交快照。省级通过表示审核完成。</p></div><el-button @click="load">刷新</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-card shadow="never"><el-form inline><el-form-item label="期次代码"><el-input v-model="periodCode" placeholder="留空查询全部可见期次" maxlength="32"/></el-form-item><el-form-item label="状态"><el-select v-model="status" clearable placeholder="本级待审" style="width:190px"><el-option v-for="(label,key) in reportStatusLabels" v-show="key!=='DRAFT'" :key="key" :value="key" :label="label"/></el-select></el-form-item><el-button @click="page=1;load()">查询</el-button><el-button @click="reset">清除</el-button></el-form><el-table v-loading="busy" :data="rows" empty-text="暂无本辖区符合条件的报表"><el-table-column prop="enterpriseName" label="企业" min-width="160"/><el-table-column prop="regionName" label="地区"/><el-table-column prop="periodLabel" label="调查期" min-width="140"/><el-table-column label="状态" min-width="130"><template #default="s">{{reportStatusLabels[s.row.status as keyof typeof reportStatusLabels]}}</template></el-table-column><el-table-column prop="baselineEmploymentCount" label="建档人数"/><el-table-column prop="periodEmploymentCount" label="调查人数"/><el-table-column prop="submissionVersion" label="提交版本"/><el-table-column label="操作"><template #default="s"><el-button link type="primary" @click="open(s.row.reportId)">详情</el-button></template></el-table-column></el-table><el-pagination v-if="total" v-model:current-page="page" :total="total" :page-size="20" layout="total,prev,pager,next" @current-change="load"/></el-card><el-drawer v-model="visible" title="报表审核详情" size="min(900px,96vw)"><div v-loading="busy" v-if="detail"><h2>{{detail.enterpriseName}}</h2><p>{{detail.organizationCode||'—'}} · {{detail.cityName}} / {{detail.regionName}} · {{detail.periodLabel}}</p><p>{{reportStatusLabels[detail.status]}} · 当前版本 {{detail.currentVersion}} · 提交版本 {{detail.submissionVersion}}</p><p>提交时间 {{formatBeijingTime(detail.submittedAt)}}</p><el-alert v-if="detail.latestReturn" :title="`${detail.latestReturn.level==='CITY'?'市级':'省级'}退回：${detail.latestReturn.comment||'未填写备注'} · ${formatBeijingTime(detail.latestReturn.reviewedAt)}`" type="warning" :closable="false"/><el-descriptions :column="1" border><el-descriptions-item v-for="(label,key) in formLabels" :key="key" :label="label">{{detail.form[key]??'—'}}</el-descriptions-item></el-descriptions><div v-if="detail.canReview" class="form-actions"><el-button type="danger" :disabled="acting||busy" @click="comment='';commentError='';returnVisible=true">退回</el-button><el-button type="primary" :disabled="acting||busy" @click="act('approve')">通过</el-button></div><p v-if="level==='province'&&detail.status==='APPROVED_PROVINCE'"><router-link :to="'/province/data/reports/'+detail.reportId">修订有效值 / 作废与追溯</router-link></p><h3>审核时间线</h3><ReviewTimeline :events="detail.reviewEvents"/><h3>全部提交快照</h3><el-collapse><el-collapse-item v-for="s in detail.snapshots" :key="s.submissionVersion" :title="`提交版本 ${s.submissionVersion} · ${formatBeijingTime(s.submittedAt)}`"><p>提交人 {{s.submittedBy}} · 备案 {{s.filingId??'旧版本未记录'}} / {{s.filingVersion??'—'}}</p><el-descriptions :column="1" border><el-descriptions-item v-for="(label,key) in formLabels" :key="key" :label="label">{{s.form[key]??'—'}}</el-descriptions-item></el-descriptions></el-collapse-item></el-collapse></div></el-drawer><el-dialog v-model="returnVisible" title="退回企业修改" width="min(520px,94vw)"><el-form label-position="top"><el-form-item label="退回备注（选填）" :error="commentError"><el-input v-model="comment" type="textarea" maxlength="500" show-word-limit :rows="4"/></el-form-item></el-form><template #footer><el-button @click="returnVisible=false">取消</el-button><el-button type="danger" :loading="acting" @click="act('return')">确认退回</el-button></template></el-dialog></section></template>
